import Link from "next/link";
import { SettingsCard } from "@/app/(app)/workspaces/[workspaceId]/settings/components/SettingsCard";
import { assertCan } from "@/lib/authorization";
import { withAuthorizationSurface } from "@/lib/authorization/context";
import { DEFAULT_LOCALE, IS_FORMBRICKS_CLOUD } from "@/lib/constants";
import { getUserLocale } from "@/lib/user/service";
import { getTranslate } from "@/lingodotdev/server";
import { getOrganizationAuth } from "@/modules/organization/lib/utils";
import { canGrantOrganizationWriteAccess } from "@/modules/organization/settings/api-keys/lib/organization-access";
import { getWorkspacesByOrganizationId } from "@/modules/organization/settings/api-keys/lib/workspaces";
import { redirectBillingRoleFromRestrictedOrgSettings } from "@/modules/settings/lib/redirect-billing-role";
import { Alert, AlertButton, AlertDescription, AlertTitle } from "@/modules/ui/components/alert";
import { PageContentWrapper } from "@/modules/ui/components/page-content-wrapper";
import { PageHeader } from "@/modules/ui/components/page-header";
import { ApiKeyList } from "./components/api-key-list";

export const APIKeysPage = async (props: Readonly<{ params: Promise<{ organizationId: string }> }>) => {
  const params = await props.params;
  const t = await getTranslate();

  await redirectBillingRoleFromRestrictedOrgSettings(params.organizationId);

  const { organization, session } = await getOrganizationAuth(params.organizationId);

  // ENG-2409: was `currentUserMembership.role === "owner" || "manager"` followed by a bare
  // `throw new Error(...)`. `organization.manage_api_keys` is the same set, and it is the exact
  // question `createApiKeyAction` already asks — so the page and the mutation behind it cannot drift
  // if that permission is ever split from `organization.manage`.
  //
  // Two deliberate changes beyond the routing:
  //   - `assertCan` throws `AuthorizationError`, which is in EXPECTED_ERROR_NAMES. The bare `Error`
  //     was not, so every unauthorized load of this page was being reported to Sentry as an
  //     unexpected exception. `app/error.tsx` renders both identically, so nothing user-visible moves.
  //   - The gate now runs BEFORE the workspace/locale fetch below rather than after it. Authorizing
  //     after reading the data it protects was harmless here (nothing was rendered) but is the wrong
  //     order to leave in place.
  await withAuthorizationSurface("page", () =>
    assertCan({ type: "user", id: session.user.id }, "organization.manage_api_keys", {
      type: "organization",
      id: organization.id,
    })
  );

  // ENG-3075: the organization-access *write* toggle mints a key that can manage the organization's
  // users, teams and workspace-team grants, so it is offered only to someone who clears
  // USER_MANAGEMENT_MINIMUM_ROLE. `createApiKeyAction` asks the same question — this only keeps the UI
  // from offering what the mutation would refuse.
  const [workspaces, locale, canGrantWriteAccess] = await Promise.all([
    getWorkspacesByOrganizationId(organization.id),
    getUserLocale(session.user.id),
    canGrantOrganizationWriteAccess(session.user.id, organization.id),
  ]);

  return (
    <PageContentWrapper>
      <PageHeader pageTitle={t("common.api_keys")} />
      {workspaces.length > 0 && (
        <Alert variant="info" role="status" className="max-w-4xl rounded-xl">
          <AlertTitle>{t("workspace.settings.api_keys.connect_app_banner_title")}</AlertTitle>
          <AlertDescription>
            {t("workspace.settings.api_keys.connect_app_banner_description")}
          </AlertDescription>
          <AlertButton asChild>
            <Link href={`/workspaces/${workspaces[0].id}/settings/workspace/app-connection`}>
              {t("workspace.settings.api_keys.connect_app_banner_link")}
            </Link>
          </AlertButton>
        </Alert>
      )}
      <SettingsCard
        title={t("common.api_keys")}
        description={t("workspace.settings.api_keys.api_keys_description")}
        bodyVariant="flush">
        <ApiKeyList
          organizationId={organization.id}
          locale={locale ?? DEFAULT_LOCALE}
          workspaces={workspaces}
          isFormbricksCloud={IS_FORMBRICKS_CLOUD}
          canGrantOrganizationWriteAccess={canGrantWriteAccess}
        />
      </SettingsCard>
    </PageContentWrapper>
  );
};

import { cn } from "@/lib/cn";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/modules/ui/components/table";
import {
  getBodyCellClassName,
  getFrameClassName,
  getHeaderCellClassName,
  getRowActivatorColumnId,
  isRowActivatable,
} from "./lib/column-classes";
import { SettingsTableSkeletonRows } from "./settings-table-skeleton";
import type { TSettingsTableProps } from "./types";

/**
 * The settings-page table: one frame, a tinted `h-12` header, divided rows.
 *
 * Columns are declared as data rather than JSX so that the header, the cells, the responsive hiding and
 * the loading skeleton all come from one source. Export the array from a `getXColumns(t, flags)` factory
 * and a `loading.tsx` can reuse it, which is what keeps a skeleton from drifting out of sync.
 *
 * Defaults to frameless, because the `<SettingsCard bodyVariant="flush">` it usually sits in already
 * provides the frame. Pass `frame="card"` when the table stands on its own.
 *
 * Deliberately has no `"use client"`: it holds no state, so a server component can render it too. Only
 * the interactive props (`onRowClick`, `getRowProps`) require a client caller.
 *
 * For anything the column API cannot express, drop down to the `Table` parts directly — they carry the
 * same visual defaults, so the escape hatch costs structural consistency but never visual consistency.
 */
export const SettingsTable = <TRow,>({
  columns,
  rows,
  getRowId,
  emptyMessage,
  frame = "none",
  isLoading = false,
  skeletonRows,
  isRowDisabled,
  footer,
  getRowProps,
  bodyProps,
  onRowClick,
  getRowLabel,
  isRowClickable,
  className,
  containerClassName,
  id,
  "aria-label": ariaLabel,
  "data-testid": dataTestId,
}: Readonly<TSettingsTableProps<TRow>>) => {
  const activatorColumnId = getRowActivatorColumnId(columns);

  const renderBody = () => {
    if (isLoading) {
      return <SettingsTableSkeletonRows columns={columns} rows={skeletonRows} />;
    }

    if (rows.length === 0) {
      return (
        <TableRow>
          <TableCell colSpan={columns.length} className="h-24 text-center text-sm text-slate-500">
            {emptyMessage}
          </TableCell>
        </TableRow>
      );
    }

    return rows.map((row, rowIndex) => {
      const isDisabled = isRowDisabled?.(row) ?? false;
      const isClickable = isRowActivatable({
        isDisabled,
        hasRowClick: Boolean(onRowClick),
        isRowClickable: isRowClickable?.(row),
      });

      return (
        <TableRow
          key={getRowId(row)}
          aria-disabled={isDisabled || undefined}
          className={cn(
            isClickable && "cursor-pointer hover:bg-slate-50",
            isDisabled && "pointer-events-none opacity-60"
          )}
          onClick={isClickable && onRowClick ? () => onRowClick(row) : undefined}
          {...getRowProps?.(row)}>
          {columns.map((column) => {
            const content = column.cell(row, rowIndex);

            return (
              <TableCell
                key={column.id}
                className={getBodyCellClassName(column)}
                onClick={column.stopRowClick ? (event) => event.stopPropagation() : undefined}>
                {isClickable && getRowLabel && column.id === activatorColumnId ? (
                  <button
                    type="button"
                    aria-label={getRowLabel(row)}
                    className="-m-1 flex w-full items-center rounded-sm p-1 text-left focus-visible:ring-2 focus-visible:ring-slate-400 focus-visible:outline-hidden">
                    {content}
                  </button>
                ) : (
                  content
                )}
              </TableCell>
            );
          })}
        </TableRow>
      );
    });
  };

  return (
    <div className={cn(getFrameClassName(frame), containerClassName)}>
      <Table id={id} aria-label={ariaLabel} data-testid={dataTestId} className={className}>
        <TableHeader>
          <TableRow className="bg-slate-100">
            {columns.map((column) => (
              <TableHead key={column.id} className={getHeaderCellClassName(column)}>
                {column.header}
                {column.header === null && column.srLabel ? (
                  <span className="sr-only">{column.srLabel}</span>
                ) : null}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody {...bodyProps}>{renderBody()}</TableBody>
      </Table>
      {footer}
    </div>
  );
};

export { SettingsTableSkeleton, SettingsTableSkeletonRows } from "./settings-table-skeleton";
export type {
  TSettingsTableAlign,
  TSettingsTableBreakpoint,
  TSettingsTableColumn,
  TSettingsTableFrame,
  TSettingsTableProps,
  TSettingsTableSkeletonProps,
} from "./types";

import { type Locale, formatDistance } from "date-fns";
import { de, enUS, es, fr, hu, ja, nl, pt, ptBR, ro, ru, sv, tr, zhCN, zhTW } from "date-fns/locale";
import { TUserLocale } from "@formbricks/types/user";
import { formatDateForDisplay } from "./utils/datetime";

const DEFAULT_LOCALE: TUserLocale = "en-US";
const TIME_SINCE_LOCALES: Record<TUserLocale, Locale> = {
  "de-DE": de,
  "en-US": enUS,
  "es-ES": es,
  "fr-FR": fr,
  "hu-HU": hu,
  "ja-JP": ja,
  "nl-NL": nl,
  "pt-BR": ptBR,
  "pt-PT": pt,
  "ro-RO": ro,
  "ru-RU": ru,
  "sv-SE": sv,
  "tr-TR": tr,
  "zh-Hans-CN": zhCN,
  "zh-Hant-TW": zhTW,
};

const isUserLocale = (locale: string): locale is TUserLocale => Object.hasOwn(TIME_SINCE_LOCALES, locale);

/** Maps locale strings to date-fns locales and falls back to English for unsupported inputs. */
const getLocaleForTimeSince = (locale: string): Locale =>
  isUserLocale(locale) ? TIME_SINCE_LOCALES[locale] : enUS;

export const timeSince = (dateString: string, locale: string = DEFAULT_LOCALE) => {
  const date = new Date(dateString);
  return formatDistance(date, new Date(), {
    addSuffix: true,
    locale: getLocaleForTimeSince(locale),
  });
};

export const timeSinceDate = (date: Date, locale: string = DEFAULT_LOCALE) => {
  return formatDistance(date, new Date(), {
    addSuffix: true,
    locale: getLocaleForTimeSince(locale),
  });
};

export const formatDate = (date: Date, locale: string = DEFAULT_LOCALE) => {
  return formatDateForDisplay(date, locale, {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
};

export const getTodaysDateTimeFormatted = (seperator: string) => {
  const date = new Date();
  const formattedDate = date.toISOString().split("T")[0].split("-").join(seperator);
  const formattedTime = date.toTimeString().split(" ")[0].split(":").join(seperator);

  return [formattedDate, formattedTime].join(seperator);
};

export const convertDatesInObject = <T>(obj: T, keysToIgnore?: Set<string>): T => {
  if (obj === null || typeof obj !== "object") {
    return obj; // Return if obj is not an object
  }
  if (Array.isArray(obj)) {
    // Handle arrays by mapping each element through the function
    return obj.map((item) => convertDatesInObject(item, keysToIgnore)) as unknown as T;
  }
  const newObj: Record<string, unknown> = {};
  for (const key in obj) {
    if (keysToIgnore?.has(key)) {
      newObj[key] = obj[key];
      continue;
    }
    if (
      (key === "createdAt" || key === "updatedAt") &&
      typeof obj[key] === "string" &&
      !isNaN(Date.parse(obj[key] as unknown as string))
    ) {
      newObj[key] = new Date(obj[key] as unknown as string);
    } else if (typeof obj[key] === "object" && obj[key] !== null) {
      newObj[key] = convertDatesInObject(obj[key], keysToIgnore);
    } else {
      newObj[key] = obj[key];
    }
  }
  return newObj as T;
};

